select OBJECT_NAME,OBJECT_TYPE,STATUS from USER_OBJECTS where OBJECT_NAME in('RRL_STOCK_HU_READ','RRL_STOCK_HU_CMD','RRL_HU_LINK_WRITE_GUARD','RRL_HU_CONTAINER_GUARD','RRL_STOCK_POSTING_API') order by OBJECT_NAME,OBJECT_TYPE;
select MIGRATION_ID,STATUS from RRL_SCHEMA_MIGRATIONS where MIGRATION_ID='2026-10-09-050-warehouse-hu-tree';
select count(*) NESTED_PARENT_DUPLICATES from (select CHILD_PALLET_UID,count(*) from RRL_WMS_HU_LINK where ACTIVE_FLAG=1 and CHILD_PALLET_UID is not null group by CHILD_PALLET_UID having count(*)>1);
